import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"guide/concepts.md","filePath":"guide/concepts.md"}'),d={name:"guide/concepts.md"};function r(i,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="concepts" tabindex="-1">Concepts <a class="header-anchor" href="#concepts" aria-label="Permalink to &quot;Concepts&quot;">​</a></h1><h2 id="voice" tabindex="-1">Voice <a class="header-anchor" href="#voice" aria-label="Permalink to &quot;Voice&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>style</code></td><td><code>beep</code>, <code>grunt</code>, <code>alphabet</code></td><td><code>beep</code></td><td>See <a href="./styles">Styles</a>.</td></tr><tr><td><code>pitch</code></td><td>−12 … +12</td><td>0</td><td>Semitones, applied to every sound.</td></tr><tr><td><code>speed</code></td><td>5 … 30</td><td>15</td><td>Characters per second. One <strong>slot</strong> is <code>1 / speed</code> seconds.</td></tr><tr><td><code>variation</code></td><td>0 … 1</td><td>0</td><td>Random pitch deviation, up to ±<code>variation × 2</code> semitones per sound.</td></tr><tr><td><code>seed</code></td><td>unsigned 32-bit</td><td>0</td><td>Changes the random choices (grunts, variation).</td></tr></tbody></table><p>Values out of range are rejected with an error (<code>PitchOutOfRange</code>, <code>SpeedOutOfRange</code>, <code>VariationOutOfRange</code>); so is a sample rate outside 8,000–192,000 Hz.</p><h2 id="timeline" tabindex="-1">Timeline <a class="header-anchor" href="#timeline" aria-label="Permalink to &quot;Timeline&quot;">​</a></h2><p>Rendering a line gives the samples and a timeline. Each <strong>event</strong> is one sound:</p><ul><li><code>start</code> and <code>duration</code>, in seconds from the start of the line;</li><li>where the character is in your text: grapheme index, UTF-8 range and UTF-16 range (Godot exposes code point indices instead, which is how its <code>String</code> counts);</li><li>the <a href="#sound-identifier">sound identifier</a>.</li></ul><p>The audio lasts until the end of the last sound plus 50 ms. A sound never lasts longer than its slot, so events never overlap.</p><h2 id="typewriter-and-advance" tabindex="-1">Typewriter and advance <a class="header-anchor" href="#typewriter-and-advance" aria-label="Permalink to &quot;Typewriter and advance&quot;">​</a></h2><p>A <strong>speaker</strong> produces one character at a time. For each character you get:</p><ul><li>its samples (empty for spaces and punctuation);</li><li>the <strong>advance</strong>: seconds to wait before the next character (1, 2 or 4 slots);</li><li>its sound identifier, if it made a sound.</li></ul><p>Feed the characters of a line to the same speaker, in order, and reset it (or create a new one) for the next line. Placing each sound at the sum of the previous advances gives exactly the samples of the whole-line render.</p><h2 id="sound-identifier" tabindex="-1">Sound identifier <a class="header-anchor" href="#sound-identifier" aria-label="Permalink to &quot;Sound identifier&quot;">​</a></h2><p>Every sound carries <code>style</code> and <code>variant</code>: which grunt (0–3), which letter (0–25), the neutral sound (26) or the beep (0). It is neutral data: map it to mouth shapes, particle effects, camera shakes or, as the playground does, to colored dots. The library itself draws nothing.</p><h2 id="determinism" tabindex="-1">Determinism <a class="header-anchor" href="#determinism" aria-label="Permalink to &quot;Determinism&quot;">​</a></h2><p>The same text, voice, seed and sample rate give the same samples, <strong>bit for bit</strong>, on every platform and binding: Linux, Windows, macOS (Apple Silicon and Intel), WebAssembly, through Rust, C, C#, GDScript and TypeScript. All math runs in a portable software implementation, and shared <a href="/reference/conformance">conformance vectors</a> check it in CI.</p><p>The random choices depend only on the style, the seed and the characters already spoken, never on the text that follows. Identical lines therefore sound identical: pass a different seed (a line id, for example) to vary them.</p><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><ul><li>Text is split into <strong>graphemes</strong>, so a composite emoji counts as one character.</li><li>Accented letters fold to their base letter; other alphabets and symbols use the style&#39;s neutral sound (or a beep, or a grunt).</li><li>Punctuation and spaces are pauses; see <a href="./styles#pauses">Styles</a>.</li></ul>',19)])])}const m=t(d,[["render",r]]);export{u as __pageData,m as default};
